package com.student.controller;
import com.student.dao.*; import com.student.model.Mark; import com.student.model.Student; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*;
public class MarksheetServlet extends HttpServlet{private final StudentDAO students=new StudentDAO();private final MarkDAO marks=new MarkDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{req.setAttribute("students",students.findAll());String id=req.getParameter("studentId");if(id!=null&&!id.isBlank()){int sid=Integer.parseInt(id);List<Mark> list=marks.findByStudent(sid);Student selected=null;for(Student s:students.findAll())if(s.getStudentId()==sid)selected=s;double total=0,max=0;for(Mark m:list){total+=m.getMarks();max+=m.getMaxMarks();}double pct=max==0?0:(total/max)*100;String grade=grade(pct);req.setAttribute("selected",selected);req.setAttribute("marks",list);req.setAttribute("total",total);req.setAttribute("maxTotal",max);req.setAttribute("percentage",pct);req.setAttribute("grade",grade);req.setAttribute("result",pct>=40?"PASS":"NEEDS IMPROVEMENT");}req.getRequestDispatcher("/marksheet.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}private String grade(double p){if(p>=90)return"A+";if(p>=80)return"A";if(p>=70)return"B+";if(p>=60)return"B";if(p>=50)return"C";if(p>=40)return"D";return"F";}}
